def proj(factor: str, value: float, year: int | None, scenario: str, source: str, url: str, note: str, low: float | None = None, high: float | None = None) -> dict[str, object]:
    return {"factorId": factor, "entity": "WLD", "value": value, "low": low, "high": high, "year": year, "scenario": scenario, "source": source, "url": url, "note": note}


def exc(factor: str, threshold: float, year: int, probability: float, basis: str, source: str, url: str, reasoning: str) -> dict[str, object]:
    return {"factorId": factor, "entity": "WLD", "threshold": threshold, "direction": "above", "year": year, "probability": probability, "basis": basis, "source": source, "url": url, "reasoning": reasoning}


